mapper.select:
SELECT * FROM dish
AND name LIKE CONCAT('%',#{keyword},'%') AND category = #{category}
AND id IN (SELECT DISTINCT dish_id FROM dish_ingredient WHERE ingredient_name LIKE CONCAT('%',#{ingredientKeyword},'%'))
AND (audit_price IS NULL OR audit_price = 0) AND id IN (SELECT DISTINCT dish_id FROM dish_ingredient)
ORDER BY code LIMIT #{offset}, #{size}

mapper.update:
UPDATE dish SET exclude_seasoning=#{excludeSeasoning}, seasoning_cost=#{seasoningCost},
ingredient_cost=#{ingredientCost}, labor_fee=#{laborFee}, other_fee=#{otherFee},
suggest_price=#{suggestPrice}, audit_price=#{auditPrice}
WHERE id=#{id}

mapper.select:
SELECT DISTINCT d.* FROM dish d
JOIN weekly_recipe wr ON wr.dish_id = d.id
WHERE wr.week_key = #{weekKey}
AND wr.meal_type = #{mealType}
